document.addEventListener('readystatechange',function(){if(document.readyState==='complete'){let a=document.querySelector('body').className;document.querySelector('body').className=a.replace(/^task-.*? /,'task-login ');$('input.kolab2facode').first().select();$('#rcmlogin2faother').click(ev=>{for(const r of document.querySelectorAll('.rcmlogin2famethodrow'))r.classList.add('hidden');for(const r of document.querySelectorAll('.rcmlogin2famethodchooserrow, .rcmlogin2famethoddirect'))r.classList.remove('hidden');ev.target.classList.add('hidden')});$('.rcmlogin2famethodchooserrow button').click(A=>{console.log(A);let b=A.target.value;for(const r of document.querySelectorAll('.rcmlogin2famethodchooserrow, .rcmlogin2famethodrow')){console.log(r);r.classList.add('hidden')}document.querySelector(`.rcmlogin2famethod${b}`)?.classList.remove('hidden');document.querySelector('#rcmlogin2faother').classList.remove('hidden')});for(const _ of document.querySelectorAll('input.kolab2facode')){let B=document.createElement('span');B.className='input-group-append';let c=document.createElement('button');c.type='submit';c.innerHTML='<i class=\"icon right\"></i>';c.className='input-group-text px-0';B.appendChild(c);_.insertAdjacentElement('afterend',B)}for(const e of document.querySelectorAll('.rcmlogin2famethodchooserrow span.input-group-prepend'))e.parentElement.removeChild(e);for(const e of document.querySelectorAll('.rcmlogin2famethodchooserrow input[type=hidden]'))e.parentElement.removeChild(e);$('input.kolab2facode').keypress(C=>console.log(C));$('#rcmlogin2facancel').click(e=>rcmail.http_post('plugin.kolab-2fa-login-cancel'))}});
